const items = $input.all();

function normDoi(doi) {
  let s = String(doi ?? '').trim().toLowerCase();
  // remove doi prefix & url forms
  s = s.replace(/^doi:\s*/i, '');
  s = s.replace(/^https?:\/\/(dx\.)?doi\.org\//i, '');
  return s;
}

function normText(t) {
  return String(t ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

for (const it of items) {
  const title = normText(it.json.title);
  const year  = String(it.json.year || '').trim();
  const doi   = normDoi(it.json.doi);

  it.json.key = doi
    ? `doi:${doi}`
    : `ty:${title}|${year || 'na'}`;
}

return items;

// ======================================================
// WF06 | Remove Duplicate
// Crossref + OpenAlex
// Mode: Run Once for All Items
// ======================================================

const items = $input.all();

const seenDOI = new Set();
const seenTitleYear = new Set();

const output = [];

// Normalize DOI
function normalizeDOI(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/^doi:\s*/i, '')
    .replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, '');
}

// Normalize Title
function normalizeTitle(value) {
  return String(value ?? '')
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ตรวจบทความทั้งหมด
for (const item of items) {

  const data = item.json;

  const doi = normalizeDOI(data.doi);
  const title = normalizeTitle(data.title);
  const year = String(data.year ?? '').trim();

  const titleYearKey =
    title && year ? `${title}|${year}` : '';

  // ตรวจสอบรายการซ้ำ
  const isDuplicate =
    (doi && seenDOI.has(doi)) ||
    (titleYearKey && seenTitleYear.has(titleYearKey));

  if (isDuplicate) {
    continue;
  }

  // บันทึก DOI
  if (doi) {
    seenDOI.add(doi);
  }

  // บันทึก Title + Year
  if (titleYearKey) {
    seenTitleYear.add(titleYearKey);
  }

  // เก็บบทความที่ไม่ซ้ำ
  output.push(item);
}

return output;

// ======================================================
// WF06 | Filter new only
// ตรวจซ้ำกับ Analysis_Master ด้วย DOI + Title/Year
// Mode: Run Once for All Items
// ======================================================

const items = $input.all();

const oldItems = items.filter(
  item => item.json.from_sheet === true
);

const newItems = items.filter(
  item => item.json.from_sheet !== true
);

const seenDoi = new Set();
const seenTitleYear = new Set();

function normalizeDoi(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/^doi:\s*/i, '')
    .replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, '')
    .trim();
}

function normalizeTitle(value) {
  return String(value ?? '')
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getIdentifiers(data) {
  const key = String(data.key ?? '');

  const keyDoi = /^\s*(?:doi:|https?:\/\/(?:dx\.)?doi\.org\/)/i.test(key)
    ? key
    : '';

  const doi = normalizeDoi(data.doi || keyDoi);
  const title = normalizeTitle(data.title);
  const year = String(data.year ?? '').trim();

  const titleYear = title
    ? `${title}|${year || 'na'}`
    : '';

  return { doi, titleYear };
}

// 1. เก็บตัวระบุของบทความเดิมใน Analysis_Master
for (const item of oldItems) {
  const { doi, titleYear } = getIdentifiers(item.json);

  if (doi) seenDoi.add(doi);
  if (titleYear) seenTitleYear.add(titleYear);
}

// 2. ตรวจบทความใหม่กับฐานข้อมูลเดิม
// และป้องกันซ้ำภายในชุดใหม่อีกชั้นหนึ่ง
const output = [];

for (const item of newItems) {
  const { doi, titleYear } = getIdentifiers(item.json);

  if (!doi && !titleYear) continue;

  const duplicated =
    (doi && seenDoi.has(doi)) ||
    (titleYear && seenTitleYear.has(titleYear));

  if (duplicated) continue;

  output.push(item);

  if (doi) seenDoi.add(doi);
  if (titleYear) seenTitleYear.add(titleYear);
}

return output;

// ======================================================
// Detect Publisher
// รองรับ OpenAlex, Crossref และ Semantic Scholar
// ตรวจจาก Publisher Raw, Journal, URL และ DOI Prefix
// Mode: Run Once for Each Item
// ======================================================

const data = $json;

// ------------------------------------------------------
// ฟังก์ชันเลือกค่าตัวแรกที่ไม่ว่าง
// ------------------------------------------------------
function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) {
      continue;
    }

    const text = String(value).trim();

    if (text !== "") {
      return text;
    }
  }

  return "";
}

// ------------------------------------------------------
// ฟังก์ชันแปลงข้อมูล URL หรือ Array ให้เป็นข้อความ
// ------------------------------------------------------
function valueToText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  if (Array.isArray(value)) {
    return value
      .map(item => valueToText(item))
      .filter(Boolean)
      .join(" ");
  }

  if (typeof value === "object") {
    return firstNonEmpty(
      value.URL,
      value.url,
      value.href,
      value.display_name,
      value.name
    );
  }

  return String(value).trim();
}

// ------------------------------------------------------
// 1. Publisher Raw
// ------------------------------------------------------
const publisherRaw = firstNonEmpty(
  data.publisher_raw,
  data.publisherRaw,
  data.host_organization_name,
  data.primary_location?.source?.host_organization_name,
  data.primary_location?.source?.display_name,
  data.publisher
);

// ------------------------------------------------------
// 2. Journal / Venue
// ------------------------------------------------------
const journal = firstNonEmpty(
  data.journal,
  data.venue,
  data.journal?.name,
  data.container_title,
  data["container-title"]?.[0],
  data.primary_location?.source?.display_name
);

// ------------------------------------------------------
// 3. DOI
// รองรับชื่อฟิลด์จากทุกแหล่งข้อมูล
// ------------------------------------------------------
const doiRaw = firstNonEmpty(
  data.doi,
  data.DOI,
  data.externalIds?.DOI,
  data.externalIds?.doi,
  data.ids?.doi,
  data.primary_location?.id
);

const doi = String(doiRaw || "")
  .replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, "")
  .replace(/^doi:\s*/i, "")
  .trim()
  .toLowerCase();

// ------------------------------------------------------
// 4. URL
// ------------------------------------------------------
const linkText = [
  valueToText(data.link),
  valueToText(data.url),
  valueToText(data.URL),
  valueToText(data.openAccessPdf?.url),
  valueToText(data.primary_location?.landing_page_url),
  valueToText(data.primary_location?.pdf_url),
  valueToText(data.resource?.primary?.URL),
  valueToText(data.links)
]
  .filter(Boolean)
  .join(" ");

// ------------------------------------------------------
// รวมข้อมูลทั้งหมดสำหรับตรวจสอบ
// ------------------------------------------------------
const sourceText = [
  publisherRaw,
  journal,
  linkText,
  doi
]
  .filter(Boolean)
  .join(" ")
  .toLowerCase();

// ------------------------------------------------------
// กฎตรวจสอบ Publisher
// เรียงจากชื่อที่จำเพาะไปยังชื่อทั่วไป
// ------------------------------------------------------
const publisherRules = [
  {
    publisher: "Elsevier",
    patterns: [
      /elsevier/,
      /elsevier\s+bv/,
      /sciencedirect\.com/,
      /ssrn\.com/,
      /10\.1016\//,
      /10\.2139\//
    ]
  },
  {
    publisher: "MDPI",
    patterns: [
      /\bmdpi\b/,
      /mdpi\s+ag/,
      /multidisciplinary digital publishing institute/,
      /mdpi\.com/,
      /10\.3390\//
    ]
  },
  {
    publisher: "IEEE",
    patterns: [
      /\bieee\b/,
      /institute of electrical and electronics engineers/,
      /ieeexplore\.ieee\.org/,
      /10\.1109\//
    ]
  },
  {
    publisher: "ACM",
    patterns: [
      /association for computing machinery/,
      /\bacm\b/,
      /dl\.acm\.org/,
      /10\.1145\//
    ]
  },
  {
    publisher: "PeerJ",
    patterns: [
      /\bpeerj\b/,
      /peerj,\s*inc/,
      /peerj\.com/,
      /10\.7717\//
    ]
  },
  {
    publisher: "Springer Nature",
    patterns: [
      /springer nature/,
      /springer science/,
      /springerlink/,
      /\bspringer\b/,
      /nature portfolio/,
      /nature publishing group/,
      /biomed central/,
      /\bbmc\b/,
      /link\.springer\.com/,
      /nature\.com/,
      /10\.1007\//,
      /10\.1038\//,
      /10\.1186\//
    ]
  },
  {
    publisher: "Wiley",
    patterns: [
      /\bwiley\b/,
      /john wiley/,
      /wiley-blackwell/,
      /onlinelibrary\.wiley\.com/,
      /10\.1002\//,
      /10\.1111\//
    ]
  },
  {
    publisher: "Taylor & Francis",
    patterns: [
      /taylor\s*(?:&|and)\s*francis/,
      /routledge/,
      /tandfonline\.com/,
      /10\.1080\//
    ]
  },
  {
    publisher: "SAGE",
    patterns: [
      /\bsage\b/,
      /sage publishing/,
      /sage publications/,
      /sagepub\.com/,
      /10\.1177\//
    ]
  },
  {
    publisher: "Frontiers",
    patterns: [
      /\bfrontiers\b/,
      /frontiersin\.org/,
      /10\.3389\//
    ]
  },
  {
    publisher: "Oxford University Press",
    patterns: [
      /oxford university press/,
      /academic\.oup\.com/,
      /10\.1093\//
    ]
  },
  {
    publisher: "Cambridge University Press",
    patterns: [
      /cambridge university press/,
      /cambridge\.org/,
      /10\.1017\//
    ]
  },
  {
    publisher: "PLOS",
    patterns: [
      /\bplos\b/,
      /public library of science/,
      /plos\.org/,
      /10\.1371\//
    ]
  },
  {
    publisher: "Emerald",
    patterns: [
      /\bemerald\b/,
      /emerald publishing/,
      /emerald\.com/,
      /10\.1108\//
    ]
  },
  {
    publisher: "IGI Global",
    patterns: [
      /igi global/,
      /igi-global\.com/,
      /10\.4018\//
    ]
  },
  {
    publisher: "Hindawi",
    patterns: [
      /\bhindawi\b/,
