// ======================================================
// Set Execution Start — WF06
// Mode: Run Once for All Items
// ======================================================

const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json,

    workflow: 'WF06 – Scholarly Paper Retrieval',
    start_ms: Date.now(),
    started_at: new Date().toISOString()
  }
}));

// ======================================================
// Build Completion Summary — WF06
// Mode: Run Once for All Items
// Input: Get Current Analysis_Master Count
// ======================================================

// ------------------------------------------------------
// 1. จำนวนปัจจุบันใน Analysis_Master
// ------------------------------------------------------
const currentMasterItems = $input.all();
const analysisMasterTotal = currentMasterItems.length;

// ------------------------------------------------------
// 2. Paper ใหม่ที่ Append ใน execution นี้
// ------------------------------------------------------
const newItems =
  $('Append row Analysis_Master').all();

const newAdded = newItems.length;

// จำนวนเดิมก่อน execution นี้
const existingBefore = Math.max(
  0,
  analysisMasterTotal - newAdded
);

// ------------------------------------------------------
// 3. นับ Paper ใหม่ตาม source
// ------------------------------------------------------
let crossrefCount = 0;
let openalexCount = 0;
let semanticScholarCount = 0;
let unknownSourceCount = 0;

for (const item of newItems) {

  const source = String(
    item.json?.source ?? ''
  )
    .trim()
    .toLowerCase()
    .replace(/[\s_-]/g, '');

  if (source === 'crossref') {
    crossrefCount++;

  } else if (source === 'openalex') {
    openalexCount++;

  } else if (source === 'semanticscholar') {
    semanticScholarCount++;

  } else {
    unknownSourceCount++;
  }
}

// จำนวน Paper ใหม่ทั้งหมดหลัง Filter/Deduplicate
const totalRetrieved =
  crossrefCount +
  openalexCount +
  semanticScholarCount +
  unknownSourceCount;

// ------------------------------------------------------
// 4. อ่านเวลาเริ่มต้น
// ------------------------------------------------------
const startData =
  $('Set Execution Start').first().json || {};

let startMs = Number(
  startData.start_ms ??
  startData.started_ms ??
  startData.start_time_ms ??
  0
);

if (!startMs) {

  const startString =
    startData.started_at ??
    startData.start_time ??
    startData.execution_start ??
    '';

  const parsed = Date.parse(startString);

  if (!Number.isNaN(parsed)) {
    startMs = parsed;
  }
}

// ------------------------------------------------------
// 5. Duration
// ------------------------------------------------------
const finishedMs = Date.now();

const durationMs =
  startMs > 0
    ? Math.max(0, finishedMs - startMs)
    : 0;

const durationSeconds =
  Math.round(durationMs / 1000);

const minutes =
  Math.floor(durationSeconds / 60);

const seconds =
  durationSeconds % 60;

const durationText =
  minutes > 0
    ? `${minutes} นาที ${seconds} วินาที`
    : `${seconds} วินาที`;

// ------------------------------------------------------
// 6. Format เวลา Bangkok
// ------------------------------------------------------
function formatBangkokTime(timestamp) {

  if (!timestamp) {
    return '-';
  }

  return new Date(timestamp).toLocaleString(
    'th-TH-u-ca-gregory',
    {
      timeZone: 'Asia/Bangkok',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    }
  );
}

const startedAt =
  startMs > 0
    ? formatBangkokTime(startMs)
    : '-';

const finishedAt =
  formatBangkokTime(finishedMs);

// ------------------------------------------------------
// 7. Execution ID
// ------------------------------------------------------
const executionId =
  String($execution.id ?? '-');

// ------------------------------------------------------
// 8. URL Analysis_Master
// ------------------------------------------------------
const analysisMasterUrl =
  String(
    startData.analysis_master_url ?? ''
  ).trim();

// ------------------------------------------------------
// 9. Output → LINE Flex
// ------------------------------------------------------
return [
  {
    json: {

      workflow:
        'WF06 – Scholarly Paper Retrieval',

      crossref_count:
        crossrefCount,

      openalex_count:
        openalexCount,

      semantic_scholar_count:
        semanticScholarCount,

      unknown_source_count:
        unknownSourceCount,

      total_retrieved:
        totalRetrieved,

      existing_before:
        existingBefore,

      new_added:
        newAdded,

      analysis_master_total:
        analysisMasterTotal,

      duration_ms:
        durationMs,

      duration_seconds:
        durationSeconds,

      duration_minutes:
        Number(
          (durationSeconds / 60).toFixed(2)
        ),

      duration_text:
        durationText,

      started_at:
        startedAt,

      finished_at:
        finishedAt,

      execution_id:
        executionId,

      analysis_master_url:
        analysisMasterUrl
    }
  }
];

// ======================================================
// Code | Build LINE Flex — WF06 Scholarly Paper Retrieval
// Mode: Run Once for Each Item
// Input: Build Completion Summary
// ======================================================

const data = $json;

// ------------------------------------------------------
// 1. อ่านข้อมูลสรุปผล WF06
// ------------------------------------------------------
const crossrefCount = Number(
  data.crossref_count ?? 0
);

const openalexCount = Number(
  data.openalex_count ?? 0
);

const semanticScholarCount = Number(
  data.semantic_scholar_count ?? 0
);

const unknownSourceCount = Number(
  data.unknown_source_count ?? 0
);

const totalRetrieved = Number(
  data.total_retrieved ?? 0
);

const existingBefore = Number(
  data.existing_before ?? 0
);

const newAdded = Number(
  data.new_added ?? 0
);

const analysisMasterTotal = Number(
  data.analysis_master_total ?? 0
);

const durationText = String(
  data.duration_text || '-'
);

const startedAt = String(
  data.started_at || '-'
);

const finishedAt = String(
  data.finished_at || '-'
);

const executionId = String(
  data.execution_id || '-'
);

const analysisMasterUrl = String(
  data.analysis_master_url || ''
).trim();

// ------------------------------------------------------
// 2. กำหนดสถานะ
// ------------------------------------------------------
let statusTitle = 'ค้นหาบทความเสร็จสมบูรณ์';
let statusIcon = '✅';

// สีน้ำเงิน
let headerColor = '#0B57D0';

let statusDetail =
  `ผ่านการกรอง ${totalRetrieved} รายการ และเพิ่มใหม่ ${newAdded} เรื่อง`;

if (totalRetrieved === 0) {

  statusTitle = 'ไม่พบบทความใหม่';
  statusIcon = 'ℹ️';
  headerColor = '#64748B';

  statusDetail =
    'ไม่พบรายการใหม่หลังการกรองและตรวจสอบความซ้ำ';

} else if (newAdded === 0) {

  statusTitle = 'ค้นหาเสร็จสมบูรณ์';
  statusIcon = 'ℹ️';
  headerColor = '#0284C7';

  statusDetail =
    `ผ่านการกรอง ${totalRetrieved} รายการ แต่ไม่มีบทความใหม่เพิ่ม`;
}

// ------------------------------------------------------
// 3. ฟังก์ชันสร้าง Metric Row
// ------------------------------------------------------
function metricRow(label, value, color = '#111827') {

  return {
    type: 'box',
    layout: 'horizontal',
    spacing: 'sm',

    contents: [
      {
        type: 'text',
        text: label,
        size: 'xs',
        color: '#64748B',
        flex: 4,
        wrap: true
      },

      {
        type: 'text',
        text: String(value),
        size: 'xs',
        color,
        weight: 'bold',
        align: 'end',
        flex: 2,
        wrap: true
      }
    ]
  };
}

// ------------------------------------------------------
// 4. สร้าง LINE Flex Bubble
// ------------------------------------------------------
const bubble = {

  type: 'bubble',
  size: 'mega',

  // ----------------------------------------------------
  // HEADER
  // ----------------------------------------------------
  header: {

    type: 'box',
    layout: 'vertical',
    backgroundColor: headerColor,
    paddingAll: '16px',
    spacing: 'xs',

    contents: [

      {
        type: 'text',
        text: `${statusIcon} ${statusTitle}`,
        color: '#FFFFFF',
        weight: 'bold',
        size: 'lg',
        wrap: true
      },

      {
        type: 'text',
        text: statusDetail,
        color: '#EAF2FF',
        size: 'xs',
        wrap: true
      }
    ]
  },

  // ----------------------------------------------------
  // BODY
  // ----------------------------------------------------
  body: {

    type: 'box',
    layout: 'vertical',
    paddingAll: '16px',
    spacing: 'sm',

    contents: [

      {
        type: 'text',
        text: '🔎 WF06 • Scholarly Paper Retrieval',
        weight: 'bold',
        size: 'sm',
        color: '#111827',
        wrap: true
      },

      {
        type: 'text',
        text: `${newAdded} บทความใหม่`,
        weight: 'bold',
        size: 'xl',
        color: '#0B57D0',
        wrap: true
      },

      {
        type: 'text',
        text:
          `หลังกรองและตัดรายการซ้ำ ${totalRetrieved} รายการ`,
        size: 'xs',
        color: '#64748B',
        wrap: true
      },

      {
        type: 'separator',
        color: '#E5E7EB',
        margin: 'sm'
      },

      // ------------------------------------------------
      // Source Metrics
      // ------------------------------------------------
      {
        type: 'text',
        text: 'แหล่งข้อมูล',
        weight: 'bold',
        size: 'xs',
        color: '#374151',
        wrap: true
      },

      metricRow(
        '📘 Crossref',
        `${crossrefCount} รายการ`,
        '#0B57D0'
      ),

      metricRow(
        '🌐 OpenAlex',
        `${openalexCount} รายการ`,
        '#0284C7'
      ),

      metricRow(
        '🎓 Semantic Scholar',
        `${semanticScholarCount} รายการ`,
        '#0369A1'
      ),

      ...(unknownSourceCount > 0
        ? [
            metricRow(
              '❓ Unknown Source',
              `${unknownSourceCount} รายการ`,
              '#F59E0B'
            )
          ]
        : []),

      {
        type: 'separator',
        color: '#E5E7EB',
        margin: 'sm'
      },

      // ------------------------------------------------
      // Analysis_Master Metrics
      // ------------------------------------------------
      {
        type: 'text',
        text: 'Analysis_Master',
        weight: 'bold',
        size: 'xs',
        color: '#374151',
        wrap: true
      },

      metricRow(
        '📄 เดิม',
        `${existingBefore} เรื่อง`
      ),

      metricRow(
        '➕ เพิ่มใหม่',
        `${newAdded} เรื่อง`,
        '#16A34A'
      ),

      metricRow(
        '📚 รวมปัจจุบัน',
        `${analysisMasterTotal} เรื่อง`,
        '#0B57D0'
      ),

      {
        type: 'separator',
        color: '#E5E7EB',
        margin: 'sm'
      },

      // ------------------------------------------------
      // เวลา
      // ------------------------------------------------
      {
        type: 'box',
        layout: 'vertical',
        spacing: 'xs',

        contents: [

          {
            type: 'text',
            text: `⏱️ ระยะเวลา: ${durationText}`,
            size: 'xs',
            color: '#374151',
            weight: 'bold',
            wrap: true
          },

          {
            type: 'text',
            text: `🟢 เริ่ม: ${startedAt}`,
            size: 'xxs',
            color: '#6B7280',
            wrap: true
          },

          {
            type: 'text',
            text: `🏁 เสร็จ: ${finishedAt}`,
            size: 'xxs',
            color: '#6B7280',
            wrap: true
          }
        ]
      },

      {
        type: 'text',
        text: `Execution ID: ${executionId}`,
        size: 'xxs',
        color: '#9CA3AF',
        wrap: true,
        margin: 'xs'
      },

{
  type: 'text',
  text: newAdded > 0
    ? `➡️ พร้อมส่งต่อ WF7: ${analysisMasterTotal} เรื่อง`
    : `✅ ไม่มีบทความใหม่ • ฐานข้อมูลสะสม ${analysisMasterTotal} เรื่อง`,
  size: 'xs',
  color: '#0B57D0',
  weight: 'bold',
  wrap: true,
  margin: 'sm'
}
    ]
  }
};

// ------------------------------------------------------
// 5. ปุ่มเปิด Analysis_Master
// ------------------------------------------------------
if (/^https?:\/\//i.test(analysisMasterUrl)) {

  bubble.footer = {

    type: 'box',
    layout: 'vertical',
    spacing: 'xs',
    paddingAll: '12px',

    contents: [

      {
        type: 'button',
        style: 'primary',
        height: 'sm',
        color: '#0B57D0',

        action: {
          type: 'uri',
          label: 'เปิด Analysis_Master',
          uri: analysisMasterUrl,

          altUri: {
            desktop: analysisMasterUrl
          }
        }
      },

      {
        type: 'text',
        text: 'Google Sheets • Analysis_Master',
        size: 'xxs',
        color: '#9CA3AF',
        align: 'center',
        margin: 'sm'
      }
    ]
  };

  bubble.styles = {
    ...(bubble.styles || {}),

    footer: {
      separator: true
    }
  };
}

// ------------------------------------------------------
// 6. Alt Text
// ------------------------------------------------------
const altText =
  totalRetrieved > 0
    ? `${statusIcon} WF06 Retrieval: เพิ่มใหม่ ${newAdded} เรื่อง`
    : `${statusIcon} WF06 Retrieval: ไม่พบบทความใหม่`;

// ------------------------------------------------------
// 7. สร้าง Flex Message
// ------------------------------------------------------
const lineMessage = {

  type: 'flex',
  altText,
  contents: bubble

};

// ------------------------------------------------------
// 8. Output
// ------------------------------------------------------
return {

  json: {

    ...data,

    // สำหรับ LineMessageNode-Flex
    line_flex_alt_text: altText,
    line_flex_contents: bubble,
    line_flex_contents_json:
      JSON.stringify(bubble),

    // Alias รองรับ Node เดิม
    alt_text: altText,
    flex_content_json:
      JSON.stringify(bubble),

    // Message พร้อมส่ง
    line_message: lineMessage,
    message: lineMessage,
    messages: [lineMessage]

  }

};

