// WF06 | Build Zero Summary

const start = $('Set Execution Start').first().json;
const oldItems = $('Get row(s) in Analysis_Master').all();

const total = oldItems.length;
const startMs = Number(start.start_ms || Date.now());
const now = Date.now();
const duration = Math.max(0, Math.round((now - startMs) / 1000));

function formatTime(ms) {
  return new Date(ms).toLocaleString(
    'th-TH-u-ca-gregory',
    {
      timeZone: 'Asia/Bangkok',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    }
  );
}

return [{
  json: {
    workflow: 'WF06 – Scholarly Paper Retrieval',

    crossref_count: 0,
    openalex_count: 0,
    semantic_scholar_count: 0,
    unknown_source_count: 0,

    total_retrieved: 0,
    new_added: 0,

    existing_before: total,
    analysis_master_total: total,

    duration_text:
      `${Math.floor(duration / 60)} นาที ${duration % 60} วินาที`,

    started_at: formatTime(startMs),
    finished_at: formatTime(now),

    execution_id: String($execution.id || '-'),
    analysis_master_url: ''
  }
}];
